//! Typed view of `schema/migrations.json`.
//!
//! Generated by `tools/extract-migrations.py` from `src/database/DatabaseSchemaHelper.cpp` and
//! embedded at compile time.  Four migrations could not be lifted as data and are hand-ported in
//! [`super::manual`]; they appear here carrying `unsupported_reason` instead of statements.

use std::sync::OnceLock;

use serde::Deserialize;

#[derive(Debug, Clone, Deserialize)]
pub struct Migrations {
    /// The schema version the C++ application is currently at.
    pub latest_version: u32,
    pub generated_by: String,
    pub source_files: Vec<String>,
    pub migrations: Vec<Migration>,
    /// The `migrate_to_*` functions that must be hand-ported.
    pub hand_ported: Vec<String>,
}

/// One step of the upgrade path, advancing the schema by exactly one version.
#[derive(Debug, Clone, Deserialize)]
pub struct Migration {
    pub from_version: u32,
    pub to_version: u32,
    /// The C++ function this came from, for tracing a statement back to its origin.
    pub cpp_function: String,
    /// Absent when the migration is hand-ported.
    #[serde(default)]
    pub statements: Option<Vec<Statement>>,
    #[serde(default)]
    pub unsupported_reason: Option<String>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Statement {
    /// SQL with `{{…}}` placeholders still in it; see [`super::render`].
    pub sql: String,
    #[serde(default)]
    pub binds: Vec<Bind>,
    /// Mirrors `QueryAndParameters::onlyRunIfPriorQueryHadResults`.
    ///
    /// Some upgrades insert based on a subquery and must not run when that subquery matches
    /// nothing.  The C++ handles this by running a trial query first and making the real one
    /// conditional on it having returned rows.
    #[serde(default)]
    pub only_if_prior_had_results: bool,
    /// A guard on whether the statement applies to this particular database.
    #[serde(default)]
    pub condition: Option<Condition>,
}

/// Mirrors the `QSqlRecord::contains` checks the C++ makes before renaming or dropping a column.
///
/// Those columns only exist in databases upgraded from an older schema: one created fresh at that
/// version never had them, and SQLite has no `DROP COLUMN IF EXISTS`.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Condition {
    /// `[table, column]`.
    ColumnExists(String, String),
}

/// A value bound to a `?` placeholder.
#[derive(Debug, Clone, PartialEq, Deserialize)]
#[serde(untagged)]
pub enum Bind {
    Bool(bool),
    Int(i64),
    Float(f64),
    Text(String),
    /// A value only known at migration time, named by the extractor as `{"$ref": "..."}`.
    Reference {
        #[serde(rename = "$ref")]
        reference: Reference,
    },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Reference {
    /// `DatabaseSchemaHelper::latestVersion`.
    LatestVersion,
    /// `QDate::currentDate()`.
    CurrentDate,
}

const MIGRATIONS_JSON: &str = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/../../../schema/migrations.json"));

/// The migration path, parsed once.
///
/// # Panics
///
/// If the embedded JSON does not match these types, which is a build-time inconsistency between
/// `tools/extract-migrations.py` and this crate.
pub fn migrations() -> &'static Migrations {
    static MIGRATIONS: OnceLock<Migrations> = OnceLock::new();
    MIGRATIONS.get_or_init(|| {
        serde_json::from_str(MIGRATIONS_JSON).expect("schema/migrations.json does not match bt_schema::Migrations")
    })
}

impl Migrations {
    /// The step that advances `from_version` by one, if there is one.
    pub fn step(&self, from_version: u32) -> Option<&Migration> {
        self.migrations.iter().find(|m| m.from_version == from_version)
    }
}
